// Generated by scripts/sync-film.mjs from motion-film/src/props/WeddingDayGarland.tsx. Edit it there, then run `npm run sync:film`.
import React from "react";
import { random } from "remotion";
import { palette } from "../theme/palette";
import { Flower, Leaf, type FlowerTone } from "./Florals";
import { qPt, type Pt } from "./WeddingDayKit";

/*
 * Varmala — the jaimaal garland: a thick loop of roses, jasmine and marigolds with a gold pendant.
 * Drawn as the front arc between two hold points A and B hanging by `sag` (scene space).
 * A and B are where the hands (or the wearer's shoulders) hold it, so it animates by those points.
 */
export const Varmala: React.FC<{ a: Pt; b: Pt; sag: number; r: number; seed: string; swing?: number; tones?: FlowerTone[] }> = ({
  a,
  b,
  sag,
  r,
  seed,
  swing = 0,
  tones = ["rose", "ivory", "orange", "rose", "ivory", "yellow"],
}) => {
  const mid: Pt = [(a[0] + b[0]) / 2 + swing, (a[1] + b[1]) / 2];
  const c: Pt = [mid[0], mid[1] + sag * 2];
  const len = Math.hypot(c[0] - a[0], c[1] - a[1]) + Math.hypot(b[0] - c[0], b[1] - c[1]);
  const n = Math.max(4, Math.floor(len / (r * 1.3)));
  const pts = new Array(n + 1).fill(0).map((_, i) => qPt(a, c, b, i / n));
  const bottom = qPt(a, c, b, 0.5);
  return (
    <g>
      {pts.map((p, i) =>
        i % 2 === 0 ? <Leaf key={`l${i}`} x={p[0]} y={p[1]} rot={random(`${seed}l${i}`) * 360} s={r / 8} color={i % 4 ? palette.green : palette.greenDeep} /> : null,
      )}
      {pts.map((p, i) => (
        <Flower key={i} x={p[0]} y={p[1]} r={r * (i % 3 === 0 ? 1.1 : 0.92)} tone={tones[i % tones.length]} rot={random(`${seed}${i}`) * 90} />
      ))}
      {/* jasmine inner strand */}
      {pts.map((p, i) =>
        i < n ? (
          <circle key={`j${i}`} cx={(p[0] + pts[i + 1][0]) / 2} cy={(p[1] + pts[i + 1][1]) / 2 - r * 0.2} r={r * 0.3} fill="#FFFDF6" />
        ) : null,
      )}
      {/* pendant */}
      <g transform={`translate(${bottom[0]} ${bottom[1] + r * 0.9})`}>
        <circle r={r * 0.62} fill="url(#foil)" />
        <circle r={r * 0.3} fill={palette.maroonLight} />
        <rect x={-0.8} y={r * 0.6} width={1.6} height={r * 1.2} fill={palette.goldLight} />
        <path d={`M${-r * 0.3} ${r * 1.8} L${r * 0.3} ${r * 1.8} L${r * 0.18} ${r * 3} L${-r * 0.18} ${r * 3} Z`} fill={palette.rose} />
      </g>
    </g>
  );
};
